6.sql:
SELECT b.title, p.name AS publisher
FROM BOOK b
JOIN PUBLISHER p ON b.publisher_id = p.publisher_id;

8.sql:
SELECT title, publish_year
FROM BOOK
WHERE publish_year > (SELECT AVG(publish_year) FROM BOOK);

9.sql:
SELECT m.member_id, m.full_name
FROM MEMBER m
WHERE EXISTS (SELECT 1 FROM LOAN l WHERE l.member_id = m.member_id);

21.sql:
SELECT m.member_id, m.full_name
FROM MEMBER m
WHERE NOT EXISTS (SELECT 1 FROM LOAN l WHERE l.member_id = m.member_id);
